class EpiFont {
	constructor() {
		// this.str = str;
	}

	text(msg, x, y, sze = 40, off = 2) { // off can be set to strokeWeight
		const xs = x;

		push();
		noFill();
		strokeJoin(BEVEL);

		// msg = msg.toUpperCase();
		for (let ch of msg) {

			switch(ch) {

					// --> special chars
				case " ":
					x += sze * 0.6;
					break;

				case "\n":
					x = xs;
					y += sze * 1.4;
					break;


				// --> a..z
				case "a":
					beginShape()
					vertex(x + sze * 0.6, y);
					vertex(x + sze * 0.6, y - sze * 0.5);
					vertex(x + sze * 0.5, y - sze * 0.6);
					vertex(x + sze * 0.3, y - sze * 0.6);
					vertex(x + sze * 0.0, y - sze * 0.45);
					vertex(x + sze * 0.0, y - sze * 0.1);
					vertex(x + sze * 0.1, y - sze * 0.0);
					vertex(x + sze * 0.3, y - sze * 0.0);
					vertex(x + sze * 0.6, y - sze * 0.15);
					endShape()
					x += sze * 0.6;
					break;

				case "b":
					beginShape()
					vertex(x + sze * 0.0, y - sze);
					vertex(x + sze * 0.0, y - sze * 0.1);
					vertex(x + sze * 0.1, y - sze * 0.0);
					vertex(x + sze * 0.3, y - sze * 0.0);
					vertex(x + sze * 0.6, y - sze * 0.15);
					vertex(x + sze * 0.6, y - sze * 0.15);
					vertex(x + sze * 0.6, y - sze * 0.5);
					vertex(x + sze * 0.5, y - sze * 0.6);
					vertex(x + sze * 0.3, y - sze * 0.6);
					vertex(x + sze * 0.0, y - sze * 0.45);
					endShape()
					x += sze * 0.6;
					break;

				case "c":
					beginShape()
					// vertex(x + sze * 0.6, y);
					vertex(x + sze * 0.6, y - sze * 0.5);
					vertex(x + sze * 0.5, y - sze * 0.6);
					vertex(x + sze * 0.3, y - sze * 0.6);
					vertex(x + sze * 0.0, y - sze * 0.45);
					vertex(x + sze * 0.0, y - sze * 0.1);
					vertex(x + sze * 0.1, y - sze * 0.0);
					vertex(x + sze * 0.3, y - sze * 0.0);
					vertex(x + sze * 0.6, y - sze * 0.1);
					endShape()
					x += sze * 0.6;
					break;

				case "d":
					beginShape()

					vertex(x + sze * 0.6, y - sze * 0.5);
					vertex(x + sze * 0.5, y - sze * 0.6);
					vertex(x + sze * 0.3, y - sze * 0.6);
					vertex(x + sze * 0.0, y - sze * 0.45);
					vertex(x + sze * 0.0, y - sze * 0.1);
					vertex(x + sze * 0.1, y - sze * 0.0);
					vertex(x + sze * 0.3, y - sze * 0.0);
					vertex(x + sze * 0.6, y - sze * 0.15);
					vertex(x + sze * 0.6, y - sze);
					endShape()
					x += sze * 0.6;
					break;

				case "e":
					beginShape()
					vertex(x + sze * 0.0, y - sze * 0.3);
					vertex(x + sze * 0.5, y - sze * 0.3);
					vertex(x + sze * 0.6, y - sze * 0.4);
