					vertex(x + sze * 0.0, y - sze * 0.1);
					vertex(x + sze * 0.2, y - sze * 0.0);
					vertex(x + sze * 0.5, y - sze * 0.0);
					vertex(x + sze * 0.6, y - sze * 0.1);
					endShape()
					x += sze * 0.6;
					break;

				case "u":
					beginShape()
					vertex(x + sze * 0.0, y - sze * 0.6);
					vertex(x + sze * 0.0, y - sze * 0.1);
					vertex(x + sze * 0.1, y - sze * 0.0);
					vertex(x + sze * 0.2, y - sze * 0.0);
