					vertex(x + sze * 0.1, y - sze * 0.0);
					vertex(x + sze * 0.2, y - sze * 0.0);
					endShape()
					x += sze * 0.2;
					break;

				// --> A..Z
				case "A":
					beginShape()
					vertex(x, y);
					vertex(x + sze * 0.3, y - sze);
					vertex(x + sze * 0.5, y - sze);
					vertex(x + sze * 0.8, y);
					endShape()
					line(x + sze * 0.12, y - sze * 0.4, x + sze * 0.68, y - sze * 0.4);
