				case "D":
					beginShape()
					vertex(x + sze * 0.8, y - sze * 0.8);
					vertex(x + sze * 0.6, y - sze);
					vertex(x, y - sze);
					vertex(x, y);
					vertex(x + sze * 0.6, y);
					vertex(x + sze * 0.8, y - sze * 0.2);
					endShapex += sze * 0.8;
					break;

				case "E":
					beginShape()
					vertex(x + sze * 0.8, y - sze);
					vertex(x + sze * 0.2, y - sze);
					vertex(x, y - sze * 0.8);
					vertex(x, y);
					vertex(x + sze * 0.8, y);
					endShape()
					line(x, y - sze/2, x + sze * 0.5, y - sze/2);
					x += sze * 0.8;
					break;

				case "F":
					beginShape()
					vertex(x + sze * 0.8, y - sze);
					vertex(x + sze * 0.2, y - sze);
					vertex(x, y - sze * 0.8);
					vertex(x, y);
					endShape()
					line(x, y - sze/2, x + sze * 0.5, y - sze/2);
					x += sze * 0.8;
					break;

				case "G": // copy C
					beginShape()
					// vertex(x + sze * 0.8, y - sze);
					vertex(x + sze * 0.8, y - sze * 0.8);
					vertex(x + sze * 0.6, y - sze);
					vertex(x + sze * 0.2, y - sze);
					vertex(x, y - sze * 0.8);
					vertex(x, y - sze * 0.2);
					vertex(x + sze * 0.2, y);
					vertex(x + sze * 0.8, y);
					vertex(x + sze * 0.8, y - sze * 0.5);
					vertex(x + sze * 0.5, y - sze * 0.5);
					endShape()
					x += sze * 0.8;
					break;

				case "H":
					line(x, y - sze, x, y);
					line(x + sze * 0.7, y - sze, x + sze * 0.7, y);
					line(x, y - sze * 0.5, x + sze * 0.7, y - sze * 0.5);
					x += sze * 0.7;
					break;

				case "I":
					beginShape()
					line(x, y - sze, x + sze * 0.2, y - sze);
					vertex(x + sze * 0.1, y - sze);
					vertex(x + sze * 0.1, y);
					line(x, y, x + sze * 0.2, y);
					endShape()
