					vertex(x + sze * 0.2, y - sze);
					vertex(x + sze * 0.5, y - sze);
					vertex(x + sze * 0.5, y - sze * 0.2);
					vertex(x + sze * 0.3, y);
					vertex(x, y);
					endShape()
					x += sze * 0.5;
